class Solution {
    public int firstDayBeenInAllRooms(int[] nextVisit){
        long[] dp=new long[nextVisit.length];
        for(int i=1;i<dp.length;i++)dp[i]=(2*dp[i-1]-dp[nextVisit[i-1]]+2+1_000_000_007)%1_000_000_007;
        return (int)dp[dp.length-1];
    }
}

code.kotlin:
class Solution {
    fun firstDayBeenInAllRooms(nextVisit:IntArray):Int{
        val mod=1_000_000_007L;
        val dp=LongArray(nextVisit.size);
        for(i in 1 until dp.size)dp[i]=(2*dp[i-1]-dp[nextVisit[i-1]]+2+mod)%mod;
        return dp.last().toInt()
    }
}

code.cpp:
class Solution {
    public: int firstDayBeenInAllRooms(vector<int>& nextVisit){
        const long long MOD=1000000007;
        vector<long long> dp(nextVisit.size());
        for(int i=1;i<(int)dp.size();++i)dp[i]=(2*dp[i-1]-dp[nextVisit[i-1]]+2+MOD)%MOD;
        return dp.back();
    }
};
